      "admin-management-order-operations__RefundQuote_Post": {
        "description": "Request body for refund quotes.",
        "oneOf": [
          {
            "$ref": "#/$defs/admin-management-order-operations__RefundQuote_ItemsRefund"
          },
          {
            "$ref": "#/$defs/admin-management-order-operations__RefundQuote_TaxAdjustmentAmount"
          }
        ]
      },
      "admin-management-order-operations__RefundQuote_ItemsRefund": {
        "type": "object",
        "required": [
          "items"
        ],
        "properties": {
          "items": {
            "type": "array",
            "items": {
              "$ref": "#/$defs/admin-management-order-operations__ItemsRefund"
            },
            "maxItems": 100
          }
        },
        "additionalProperties": false
      },
      "admin-management-order-operations__ItemsRefund": {
        "oneOf": [
          {
            "$ref": "#/$defs/admin-management-order-operations__QuantityBoundItem"
          },
          {
            "$ref": "#/$defs/admin-management-order-operations__AmountBoundItem"
          },
          {
            "$ref": "#/$defs/admin-management-order-operations__TaxExemptItem"
          },
          {
            "$ref": "#/$defs/admin-management-order-operations__FeeItem"
          }
        ]
      },
      "admin-management-order-operations__QuantityBoundItem": {
        "type": "object",
        "required": [
          "item_type",
          "item_id",
          "quantity"
        ],
        "description": "Quantity Bound Item\n\nType of refund item that capture refunding of items in the order that are of type quantity.\n* `PRODUCT`\n* `GIFT_WRAPPING`\n",
        "properties": {
          "item_type": {
            "$ref": "#/$defs/admin-management-order-operations__QuantityBoundItemItemType",
            "description": "Type of refund."
          },
          "item_id": {
            "type": "integer",
            "description": "Order Product ID.",
            "minimum": -9007199254740991,
            "maximum": 9007199254740991
          },
          "adjustments": {
            "type": "array",
            "description": "Array of product refund deductions",
            "items": {
              "$ref": "#/$defs/admin-management-order-operations__RefundItemAdjustment"
            },
            "maxItems": 100
          },
          "quantity": {
            "type": "integer",
            "minimum": -9007199254740991,
            "maximum": 9007199254740991
          },
          "reason": {
            "type": "string",
            "minLength": 0,
            "maxLength": 1000,
            "description": "Reason for refund."
          }
        },
        "additionalProperties": false
      },
      "admin-management-order-operations__QuantityBoundItemItemType": {
        "type": "string",
        "enum": [
          "PRODUCT",
          "GIFT_WRAPPING"
        ],
        "description": "Type of refund.",
        "maxLength": 262144
      },
      "admin-management-order-operations__RefundItemAdjustment": {
        "type": "object",
        "description": "Use to reduce the amount refunded for an item.",
        "properties": {
          "amount": {
            "type": "string",
            "description": "A negative 2 decimal place rounded value to deduct from the amount refunded.",
            "maxLength": 262144
          },
          "description": {
            "type": "string",
            "minLength": 0,
            "maxLength": 255,
            "description": "Description of reason for the adjustment."
          }
        },
        "additionalProperties": false
      },
      "admin-management-order-operations__AmountBoundItem": {
        "type": "object",
        "required": [
          "item_type",
          "item_id",
          "amount"
        ],
        "description": "Amount Bound Item\n\nType of refund item that capture refunding of items in the order that are of type amount.\n* `ORDER`\n* `SHIPPING`\n* `HANDLING`\n* `TAX`\n* `FEE`",
        "properties": {
          "item_type": {
            "$ref": "#/$defs/admin-management-order-operations__AmountBoundItemItemType",
            "description": "Type of refund."
          },
          "item_id": {
            "type": "integer",
            "description": "Order address ID.",
            "minimum": -9007199254740991,
            "maximum": 9007199254740991
          },
          "amount": {
            "$ref": "#/$defs/admin-management-order-operations__Amount"
          },
          "reason": {
            "type": "string",
            "minLength": 0,
            "maxLength": 1000,
            "description": "Explanation of refund."
          }
        },
        "additionalProperties": false
      },
