      "admin-content-marketing__coupon_Base": {
        "type": "object",
        "required": [
          "name",
          "type",
          "amount",
          "code",
          "applies_to"
        ],
        "properties": {
          "name": {
            "type": "string",
            "maxLength": 100,
            "description": "The name of the coupon. The value must be unique."
          },
          "type": {
            "$ref": "#/$defs/admin-content-marketing__CouponBaseType"
          },
          "amount": {
            "type": "string",
            "description": "The discount to apply to an order, as either an amount or a percentage. This field’s usage is determined by the coupon `type`. For example, a `type` of + `percentage_discount` would determine a percentage here.",
            "maxLength": 262144
          },
          "min_purchase": {
            "type": "string",
            "description": "Specifies a minimum value that an order must have before the coupon can be applied to it.",
            "maxLength": 262144
          },
          "expires": {
            "type": "string",
            "description": "Specifies when a coupon expires. Coupons need not have an expiry date – you can also control expiry via + `max_uses` or `max_uses_per_customer`. If you do use this date field, the value must be in <a href=\"http://tools.ietf.org/html/rfc2822#section-3.3\" target=\"_blank\">RFC 2822</a> format.",
            "maxLength": 262144
          },
          "enabled": {
            "type": "boolean",
            "description": "If the coupon is enabled, this field’s value is `true`; otherwise, `false`."
          },
          "code": {
            "type": "string",
            "maxLength": 50,
            "pattern": "[a-zA-Z0-9_ -]",
            "description": "The coupon code that customers will use to receive their discounts. Value must be unique. Only letters, numbers, white space, underscores, and hyphens are allowed."
          },
          "applies_to": {
            "$ref": "#/$defs/admin-content-marketing__CouponBaseAppliesTo",
            "description": "If it is not included in the PUT request, its existing value on the coupon will be cleared. Also required to be set on the POST request"
          },
          "max_uses": {
            "type": "integer",
            "description": "Maximum number of times this coupon can be used.",
            "minimum": -9007199254740991,
            "maximum": 9007199254740991
          },
          "max_uses_per_customer": {
            "type": "integer",
            "description": "Maximum number of times each customer can use this coupon.",
            "minimum": -9007199254740991,
            "maximum": 9007199254740991
          },
          "restricted_to": {
            "$ref": "#/$defs/admin-content-marketing__CouponBaseRestrictedTo"
          },
          "shipping_methods": {
            "type": "array",
            "description": "This is a list of shipping-method names. A shipping method must be enabled on the store to use it with a coupon. To check which shipping methods are enabled, please use the [List Shipping Methods](/developer/docs/archive/store-operations/v2-catalog-products/v2-products#list-shipping-methods) endpoint.",
            "items": {
              "type": "string",
              "maxLength": 262144
            },
            "maxItems": 10
          }
        },
        "additionalProperties": false
      },
      "admin-content-marketing__CouponBaseType": {
        "type": "string",
        "enum": [
          "per_item_discount",
          "per_total_discount",
          "shipping_discount",
          "free_shipping",
          "percentage_discount",
          "promotion"
        ],
        "maxLength": 262144
      },
      "admin-content-marketing__CouponBaseAppliesTo": {
        "type": "object",
        "description": "If it is not included in the PUT request, its existing value on the coupon will be cleared. Also required to be set on the POST request",
        "properties": {
          "ids": {
            "type": "array",
            "description": "ID of either the products or categories",
            "items": {
              "type": "integer",
              "minimum": -9007199254740991,
              "maximum": 9007199254740991
            },
            "maxItems": 10
          },
          "entity": {
            "type": "string",
            "description": "What the discount applies to. Can be products or categories.",
            "maxLength": 262144
          }
        },
        "additionalProperties": false
      },
      "admin-content-marketing__CouponBaseRestrictedTo": {
        "type": "object",
        "properties": {
          "countries": {
            "type": "string",
            "maxLength": 262144
          }
        },
        "additionalProperties": false
      },
      "admin-content-marketing__giftCertificate_Put": {
        "type": "object",
        "required": [
          "to_name",
          "to_email",
          "from_name",
          "from_email",
          "amount"
        ],
        "properties": {
          "to_name": {
            "type": "string",
            "description": "Name of the recipient.",
            "maxLength": 262144
          },
          "to_email": {
            "type": "string",
            "description": "Email of the recipient.",
            "maxLength": 262144
          },
          "from_name": {
            "type": "string",
            "description": "Name of the customer who purchased the gift certificate.",
            "maxLength": 262144
          },
          "from_email": {
            "type": "string",
            "description": "Email of the customer who purchased the gift certificate.",
            "maxLength": 262144
          },
          "amount": {
            "type": "string",
            "description": "Value of the gift certificate.",
            "maxLength": 262144
          },
          "balance": {
            "type": "string",
            "description": "The remaining value of the gift certificate. If not set, will default to the amount.",
            "maxLength": 262144
          },
          "purchase_date": {
            "type": "string",
            "description": "Date the gift certificate was purchased. If not assigned, this will be set to today’s date. Enter date in RFC-2822 format.",
            "maxLength": 262144
          },
          "expiry_date": {
            "type": "string",
            "description": "Date on which the gift certificate is set to expire.",
            "maxLength": 262144
          },
          "customer_id": {
            "type": "integer",
            "description": "The ID of the customer placing the order.",
            "minimum": -9007199254740991,
            "maximum": 9007199254740991
          },
          "template": {
            "$ref": "#/$defs/admin-content-marketing__GiftCertificatePutTemplate",
            "description": "The email theme to use in the message sent to the recipient."
          },
          "message": {
            "type": "string",
            "description": "Text that will be sent to the recipient, such as “Congratulations.”",
            "maxLength": 262144
          },
          "code": {
            "type": "string",
            "maxLength": 255,
            "description": "A unique string that a customer can input to redeem a gift certificate. Values greater than 20 characters will be trimmed down to the first 20 characters and returned in the response.\nIf this field is not set, a value will be autogenerated."
          },
          "status": {
            "$ref": "#/$defs/admin-content-marketing__GiftCertificatePutStatus"
          },
          "currency_code": {
            "type": "string",
            "description": "A currency code, following the ISO 4217 standard. The currency has to exist in the store first.\n\nGift Certificates can only be used if the transactional currency of the cart is the same as the one defined in the gift certificate. If this value is not provided, the gift certificate is created using the store's default transactional currency.",
            "maxLength": 262144
          }
        },
        "additionalProperties": false
      },
