      "admin-management-promotion-settings__GlobalPromotionSettings": {
        "type": "object",
        "required": [
          "promotions_apply_on_products_with_custom_product_price",
          "promotions_triggered_by_products_with_zero_product_price",
          "number_of_coupons_allowed_at_checkout",
          "promotions_applied_on_original_product_price"
        ],
        "properties": {
          "promotions_apply_on_products_with_custom_product_price": {
            "type": "boolean",
            "description": "- When the property is set to \"true\", promotions will apply for products with custom pricing.\n- When the property is set to \"false\", promotions will not apply for products with custom pricing.\n- Note: This field can only be edited for Enterprise Accounts."
          },
          "promotions_triggered_by_products_with_zero_product_price": {
            "type": "boolean",
            "description": "- When the property is set to \"true\", promotions will be triggered by zero price products.\n- When the property is set to \"false\", promotions will not be triggered by zero price products.\n- Note: This field can only be edited for Enterprise Accounts."
          },
          "number_of_coupons_allowed_at_checkout": {
            "type": "integer",
            "minimum": 1,
            "maximum": 5,
            "description": "Specifies the number of coupons allowed at checkout on a single order.\n- Note: This field can only be edited for Enterprise Accounts."
          },
          "promotions_applied_on_original_product_price": {
            "type": "boolean",
            "description": "- When the property is set to \"true\", promotions in a cart are calculated independently, each applied to the original price of the included products.\n- When the property is set to \"false\", promotions in a cart are calculated cumulatively, applied to the order sub-total based on your promotion order."
          }
        },
        "additionalProperties": false
      },
