      "admin-management-promotions__Customer": {
        "type": "object",
        "description": "Specifies the requirements which make the customer eligible for the promotion.\n\nNote:\n- Only \"group_ids\" or \"excluded_group_ids\" should be specified (have non-empty array data), but not both.\n- group_id zero (0) signifies guest customers or registered customers who are not assigned to any groups.\n- The \"group_ids\" array has a hard limit of 100000 group ids.",
        "properties": {
          "group_ids": {
            "type": "array",
            "description": "A list of customer group IDs that the promotion targets. Only customers in those groups are eligible for this promotion. When unspecified, or set to an empty array, this requirement is not effective, and all customers who satisfy the other requirements (minimum_order_count, excluded_group_ids) are eligible for the promotion. This has a maximum supported length of 100000 IDs.",
            "items": {
              "type": "integer",
              "minimum": -9007199254740991,
              "maximum": 9007199254740991
            },
            "maxItems": 10
          },
          "minimum_order_count": {
            "type": "integer",
            "description": "The minimum number of completed orders required of the customer.",
            "minimum": -9007199254740991,
            "maximum": 9007199254740991
          },
          "excluded_group_ids": {
            "type": "array",
            "description": "A list of customer group IDs that the promotion will exclude. Only customers who are NOT in those groups are eligible for this promotion. When unspecified, or set to an empty array, this requirement will not have any effects, and all customers who satisfy the other requirements (group_ids, minimum_order_count) are eligible for the promotion.",
            "items": {
              "type": "integer",
              "minimum": -9007199254740991,
              "maximum": 9007199254740991
            },
            "maxItems": 10
          },
          "segments": {
            "$ref": "#/$defs/admin-management-promotions__CustomerSegments"
          }
        },
        "additionalProperties": false
      },
