      "admin-management-promotions__Rule": {
        "type": "object",
        "required": [
          "action"
        ],
        "description": "**Rule**\nA Rule is the executable unit of the promotion. When a ruleʼs condition is met, the API applies the discount defined in the specified action.",
        "properties": {
          "action": {
            "$ref": "#/$defs/admin-management-promotions__Action"
          },
          "apply_once": {
            "type": "boolean",
            "description": "Setting this property to false enables the rule to run repeatedly (for example: 1 free product X for every product Y you purchase)"
          },
          "stop": {
            "type": "boolean",
            "description": "Boolean value that specifies whether to stop executing all the remaining rules down the priority list when the current rule is applied successfully."
          },
          "condition": {
            "$ref": "#/$defs/admin-management-promotions__Condition"
          }
        },
        "additionalProperties": false
      },
      "admin-management-promotions__Action": {
        "description": "**Action**",
        "oneOf": [
          {
            "$ref": "#/$defs/admin-management-promotions__CartValueAction"
          },
          {
            "$ref": "#/$defs/admin-management-promotions__CartItemsAction"
          },
          {
            "$ref": "#/$defs/admin-management-promotions__GiftItemAction"
          },
          {
            "$ref": "#/$defs/admin-management-promotions__FixedPriceSetAction"
          },
          {
            "$ref": "#/$defs/admin-management-promotions__ShippingAction"
          },
          {
            "$ref": "#/$defs/admin-management-promotions__ShippingDiscountAction"
          }
        ]
      },
      "admin-management-promotions__CartValueAction": {
        "type": "object",
        "description": "**Cart Value Action**\nApplies discount on the entire cart.",
        "properties": {
          "cart_value": {
            "$ref": "#/$defs/admin-management-promotions__CartValueActionCartValue"
          }
        },
        "additionalProperties": false
      },
      "admin-management-promotions__CartValueActionCartValue": {
        "type": "object",
        "required": [
          "discount"
        ],
        "properties": {
          "discount": {
            "$ref": "#/$defs/admin-management-promotions__Discount"
          },
          "maximum_allowed_discount_amount": {
            "$ref": "#/$defs/admin-management-promotions__MaximumAllowedDiscountAmount"
          }
        },
        "additionalProperties": false
      },
      "admin-management-promotions__Discount": {
        "description": "**Discount**",
        "oneOf": [
          {
            "$ref": "#/$defs/admin-management-promotions__FixedDiscount"
          },
          {
            "$ref": "#/$defs/admin-management-promotions__PercentageDiscount"
          }
        ]
      },
      "admin-management-promotions__FixedDiscount": {
        "type": "object",
        "required": [
          "fixed_amount"
        ],
        "description": "**Fixed Discount**",
        "properties": {
          "fixed_amount": {
            "$ref": "#/$defs/admin-management-promotions__Money"
          }
        },
        "additionalProperties": false
      },
      "admin-management-promotions__Money": {
        "type": "string",
        "pattern": "[0-9]+(\\.[0-9]+)?",
        "description": "**Money**\nRepresents a monetary value in the store’s default currency.",
        "maxLength": 262144
      },
      "admin-management-promotions__PercentageDiscount": {
        "type": "object",
        "required": [
          "percentage_amount"
        ],
        "description": "**Percentage Discount**",
        "properties": {
          "percentage_amount": {
            "type": "string",
            "description": "The amount of discount (percentage off) to apply.",
            "maxLength": 262144
          }
        },
        "additionalProperties": false
      },
      "admin-management-promotions__MaximumAllowedDiscountAmount": {
        "type": "string",
        "pattern": "^(0|([1-9][0-9]*))(\\.[0-9]+)?$",
        "description": "The maximum monetary value that can be applied as a discount. It can take any value greater than 0, up to 10000000.\nThe application of this maximum depends on the discount type:\n  - Discount on shipping:\n      - Percent Discount: Maximum discount total applies to ALL shipping destinations combined.\n      - Fixed Amount Discount: Maximum total is divided evenly amongst all shipping destinations.\n  - Discount on products:\n      - Percent Discount: Maximum discount total applies to ALL products combined.\n      - Fixed Amount Discount + Each Product's price: Maximum total is divided based on existing weighting logic amongst all products. Applicable only when `as_total` is set to `false`.\n  - Discount on order subtotal:\n      - Maximum discount total applies to entire order total. Applicable for both Percent and Fixed Amount discounts.\n",
        "maxLength": 262144
      },
      "admin-management-promotions__CartItemsAction": {
        "type": "object",
        "description": "**Cart Items Action**\nApplies discount on matching products in the cart.",
        "properties": {
          "cart_items": {
            "$ref": "#/$defs/admin-management-promotions__CartItemsActionCartItems"
          }
        },
        "additionalProperties": false
      },
      "admin-management-promotions__CartItemsActionCartItems": {
        "type": "object",
        "required": [
          "discount"
        ],
        "properties": {
          "discount": {
            "$ref": "#/$defs/admin-management-promotions__Discount"
          },
          "maximum_allowed_discount_amount": {
            "$ref": "#/$defs/admin-management-promotions__MaximumAllowedDiscountAmount"
          },
          "as_total": {
            "type": "boolean",
            "description": "Set this value to true to distribute the discount as a total among matching items. By default, the discount applies to each item.\nExample: If set to false, the discount is $10 and you have 2 eligible items for this discount in the cart, both items will be discounted by $10, with a total of $20 off the order.\nIf set to true, $10 will be distributed among the 2 items, weighted by their respective price. In a case where there are 2 of the same items, each item will be discounted by $5."
          },
          "items": {
            "$ref": "#/$defs/admin-management-promotions__ItemMatcher"
          },
          "include_items_considered_by_condition": {
            "type": "boolean",
            "description": "Setting this value to true enables you to discount items that are used to satisfy the condition. By default items that are used to satisfy the condition are excluded from receiving the discount. For example, \"Buy 1 Get 1 20% off.\" When the cart only contains 1 item, the discount won’t apply."
          },
          "exclude_items_on_sale": {
            "type": "boolean",
            "description": "Setting this value to true enables the option to prevent items already on sale from being further discounted."
          },
          "strategy": {
            "$ref": "#/$defs/admin-management-promotions__CartItemsActionCartItemsStrategy",
            "description": "If the shopper has multiple items in their cart that could be discounted by this action, strategy will determine which items are discounted, for example LEAST_EXPENSIVE will sort items by their price in ascending order and discount the cheapest item first."
          },
          "quantity": {
            "type": "integer",
            "description": "Specifies a quantity of matching items to discount. If no quantity is specified, an infinite number of items can be discounted.",
            "minimum": -9007199254740991,
            "maximum": 9007199254740991
          },
          "add_free_item": {
            "type": "boolean",
            "description": "The promotion will try to add a free item to the cart automatically, but if it cannot, it will discount a matching existing cart item by 100%."
          }
        },
        "additionalProperties": false
      },
