        "type": "string",
        "enum": [
          "AUTOMATIC"
        ],
        "description": "The type of the promotion. Promotions applied automatically have a value of `AUTOMATIC` whereas promotions requiring a coupon have a value of `COUPON`.",
        "maxLength": 262144
