      "admin-payments-payment-transactions__AvsResult": {
        "type": "object",
        "description": "Address Verification System (AVS) result returned by the payment provider.",
        "properties": {
          "code": {
            "type": "string",
            "description": "AVS response code from the processor or issuer.\nKnown values are documented but providers may return additional proprietary codes.\n\nCommon values:\n  - A: Street address matches, but postal code does not\n  - B: Street address matches, but postal code not verified\n  - C: Street address and postal code do not match\n  - D: Street address and postal code match\n  - E: AVS data is invalid or AVS is not allowed for this card type\n  - F: Card member's name does not match, but billing postal code matches\n  - G: Non-U.S. issuing bank does not support AVS\n  - H: Card member's name does not match; street address and postal code match\n  - I: Address not verified\n  - J: Card member's name, billing address, and postal code match; shipping information verified, and chargeback protection guaranteed\n  - K: Card member's name matches, but billing address and billing postal code do not match\n  - L: Card member's name and billing postal code match, but billing address does not match\n  - M: Street address and postal code match\n  - N: Street address and postal code do not match\n  - O: Card member's name and billing address match, but billing postal code does not match\n  - P: Postal code matches, but street address not verified\n  - Q: Card member's name, billing address, and postal code match; shipping information verified, but chargeback protection not guaranteed\n  - R: System unavailable\n  - S: U.S. issuing bank does not support AVS\n  - T: Card member's name does not match, but street address matches\n  - U: Address information unavailable\n  - V: Card member's name, billing address, and billing postal code match\n  - W: Street address does not match, but 9-digit postal code matches\n  - X: Street address and 9-digit postal code match\n  - Y: Street address and 5-digit postal code match\n  - Z: Street address does not match, but 5-digit postal code matches\n",
            "maxLength": 262144
          },
          "message": {
            "type": "string",
            "description": "Human-readable explanation of the AVS verification result.",
            "maxLength": 262144
          },
          "street_match": {
            "type": "string",
            "description": "Street address match indicator.\nKnown values are documented but providers may add other values.\n\nCommon values:\n  - Y: Street address matches\n  - N: Street address does not match\n  - U: Street address match unavailable or not verified\n",
            "maxLength": 262144
          },
          "postal_match": {
            "type": "string",
            "description": "Postal/ZIP code match indicator.\nKnown values are documented but providers may add other values.\n\nCommon values:\n  - Y: Postal code matches\n  - N: Postal code does not match\n  - U: Postal code match unavailable or not verified\n",
            "maxLength": 262144
          }
        },
        "additionalProperties": false
      },
      "admin-payments-payment-transactions__CvvResult": {
        "type": "object",
        "description": "Card Verification Value (CVV) result returned by the payment provider.",
        "properties": {
          "code": {
            "type": "string",
            "description": "CVV result code returned by the payment provider.\n\nCommon values:\n  - D: Suspicious\n  - I: Invalid\n  - M: Match\n  - N: No match\n  - P: Not processed\n  - S: Missing\n  - U: Unprocessable\n  - X: Not supported\n\nAdditional values may be returned by the payment provider.\n",
            "maxLength": 262144
          },
          "message": {
            "type": "string",
            "description": "Human-readable explanation of the CVV verification result.",
            "maxLength": 262144
          }
        },
        "additionalProperties": false
      },
